"""Inline source selection; no manual money entry or inferred evidence."""
HTML='''<details id="so-treasury-panel" class="so-step so-conditions"><summary>VINCULAR CAJA, BANCOS Y PREVISIONES</summary><p>Selecciona los saldos recibidos de esta empresa y corte para utilizarlos en ventas. No se modifican los documentos originales. La selección declara su uso para la simulación; no acredita una conciliación.</p><button id="so-treasury-load" type="button">Buscar archivos recibidos de esta empresa</button><p id="so-treasury-scope"></p><label>Saldos contables recibidos<select id="so-treasury-balance"><option value="">Carga los archivos disponibles</option></select></label><p id="so-treasury-identity" role="status"></p><label><input id="so-treasury-identity-ack" type="checkbox"> Si el código o la escritura de la razón social difieren, confirmo que los archivos seleccionados pertenecen a la empresa activa indicada arriba. Esta declaración queda registrada.</label><div id="so-treasury-accounts"></div><p id="so-treasury-total" class="so-payment-summary" aria-live="polite"></p><label>Calendario de cobros y pagos<select id="so-treasury-flows"><option value="">Usar previsión de base, sin calendario recibido</option></select></label><p>El calendario elegido sustituye el utilizado en ventas; no se suma al anterior. No presupone movimientos cobrados o pagados.</p><div class="fields"><label>Responsable<input id="so-treasury-actor" maxlength="500"></label><label>Motivo de la selección<input id="so-treasury-reason" maxlength="500"></label></div><label><input id="so-treasury-ack" type="checkbox"> Confirmo que las cuentas seleccionadas son los saldos disponibles que declaro para esta simulación, sin duplicar niveles contables ni incluir saldos restringidos. He revisado su cobertura.</label><button id="so-treasury-save" type="button">Vincular estos datos a ventas</button><button id="so-treasury-clear" type="button">Retirar vínculo y recuperar fuentes anteriores</button><p id="so-treasury-notice" role="status"></p></details>'''
JS=r'''
let salesTreasurySources=null,salesTreasuryDataset=null,salesTreasuryVersion=0;
async function openSalesTreasury(){const panel=$('so-treasury-panel');panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});await loadSalesTreasury()}
async function loadSalesTreasury(){const dataset=$('dataset').value,seq=++salesTreasuryVersion;salesTreasurySources=null;salesTreasuryDataset=null;$('so-treasury-accounts').replaceChildren();$('so-treasury-total').textContent='';$('so-treasury-ack').checked=false;$('so-treasury-identity-ack').checked=false;$('so-treasury-identity').textContent='';try{const r=await api('/api/sales-proposals/treasury/options',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset})});if(dataset!==$('dataset').value||seq!==salesTreasuryVersion)return;salesTreasurySources=r;salesTreasuryDataset=dataset;$('so-treasury-scope').textContent=r.company_name+' · Código '+r.company_id+' · Corte '+stockDate(r.as_of_date);for(const [id,kind,empty] of [['so-treasury-balance','balance','Selecciona un archivo de saldos'],['so-treasury-flows','cash_flow','Usar previsión de base, sin calendario recibido']]){const select=$(id);select.replaceChildren();option(select,'',empty);r.batches.filter(b=>b.kind===kind).forEach(b=>option(select,b.batch_id,b.filename+' · '+(b.sheet||kind)+' · '+b.company_id+(b.requires_identity_confirmation?' · Confirmar identidad':'')))}$('so-treasury-notice').textContent=r.batches.some(b=>b.kind==='balance')?'Selecciona el archivo y marca las cuentas que quieres utilizar.':'No hay saldos compatibles con la empresa y corte activos. Revisa la identificación con la que se recibió el archivo; no se vinculan empresas distintas automáticamente. '+(r.excluded||[]).map(x=>x.filename+' · '+x.legal_name+' ('+x.company_id+') · '+stockDate(x.as_of_date)+' · '+x.reason).join(' | ')}catch(e){if(dataset===$('dataset').value&&seq===salesTreasuryVersion)$('so-treasury-notice').textContent=e.message}}
function showSalesTreasuryIdentity(){const ids=[$('so-treasury-balance').value,$('so-treasury-flows').value],items=salesTreasurySources?.batches.filter(b=>ids.includes(b.batch_id))||[];$('so-treasury-identity-ack').checked=false;$('so-treasury-identity').textContent=items.map(b=>'Archivo: '+b.legal_name+' · código '+b.company_id+(b.requires_identity_confirmation?' — requiere confirmar que es la empresa activa.':' — identidad coincidente.')).join(' | ')}
$('so-treasury-flows').onchange=showSalesTreasuryIdentity;
$('so-treasury-balance').onchange=()=>{showSalesTreasuryIdentity();const box=$('so-treasury-accounts');box.replaceChildren();$('so-treasury-ack').checked=false;const batch=salesTreasurySources?.batches.find(b=>b.batch_id===$('so-treasury-balance').value);(batch?.accounts||[]).forEach(a=>{const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.dataset.treasuryAccount=a.code;check.dataset.amount=a.balance;label.append(check,document.createTextNode(a.code+' · '+money(a.balance)+' '+a.currency));box.append(label);check.onchange=()=>{$('so-treasury-ack').checked=false;updateSalesTreasuryTotal()}});updateSalesTreasuryTotal()};
function updateSalesTreasuryTotal(){const checks=[...$('so-treasury-accounts').querySelectorAll('input:checked')];$('so-treasury-total').textContent=checks.length?'Suma orientativa de '+checks.length+' cuentas: '+money(checks.reduce((n,c)=>n+Number(c.dataset.amount),0))+' EUR. El servidor comprobará duplicados, niveles y moneda antes de vincular.':'Marca cuentas 570/572 o sus subcuentas. No selecciones simultáneamente una cuenta y sus subcuentas.'}
async function saveSalesTreasury(clear){const dataset=$('dataset').value,version=salesOfferVersion;if(!clear&&!$('so-treasury-balance').value){$('so-treasury-notice').textContent='Selecciona un archivo de saldos. Si la lista está vacía, pulsa Buscar archivos y revisa el diagnóstico de empresa y corte.';return}if(salesTreasuryDataset!==dataset||!salesTreasurySources){$('so-treasury-notice').textContent='Busca primero los archivos de esta empresa.';return}const batch=$('so-treasury-balance').value,flow=$('so-treasury-flows').value,ids=[batch,flow].filter(Boolean),fingerprints=Object.fromEntries(ids.map(id=>[id,salesTreasurySources.batches.find(b=>b.batch_id===id)?.fingerprint]));$('so-treasury-save').disabled=$('so-treasury-clear').disabled=true;invalidateSalesProposal();try{const r=await api('/api/sales-proposals/treasury/select',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,balance_batch:batch,flow_batch:flow||null,account_codes:[...$('so-treasury-accounts').querySelectorAll('input:checked')].map(c=>c.dataset.treasuryAccount),source_fingerprints:fingerprints,actor:$('so-treasury-actor').value.trim(),reason:$('so-treasury-reason').value.trim(),acknowledge:$('so-treasury-ack').checked,confirm_identity:$('so-treasury-identity-ack').checked,clear})});if(dataset!==$('dataset').value||version!==salesOfferVersion)return;state=await api('/api/state?dataset='+encodeURIComponent(dataset));if(dataset!==$('dataset').value||version!==salesOfferVersion)return;invalidateSalesProposal();$('so-treasury-notice').textContent=r.status==='CLEARED'?'Vínculo retirado. Evalúa de nuevo.':'Datos vinculados con su procedencia. Evalúa de nuevo para utilizar esta selección; los precios y cantidades introducidos se conservan.';$('so-notice').textContent='La fuente financiera ha cambiado. Evalúa de nuevo la propuesta.'}catch(e){if(dataset===$('dataset').value)$('so-treasury-notice').textContent=e.message}finally{$('so-treasury-save').disabled=$('so-treasury-clear').disabled=false}}
$('so-treasury-load').onclick=loadSalesTreasury;$('so-treasury-save').onclick=()=>saveSalesTreasury(false);$('so-treasury-clear').onclick=()=>saveSalesTreasury(true);
'''
